'use client';

import React, { useState } from 'react';
import { ClientProfileData, TransactionEvidence, DisputeCase } from '../lib/types';
import { MOCK_CUSTOMER_PROFILE } from '../lib/data';

interface ClientProfileProps {
  isRealMode: boolean;
  realTxEvidence?: TransactionEvidence | null;
  realCase?: DisputeCase | null;
  simulatedProfile?: ClientProfileData;
}

export const ClientProfile: React.FC<ClientProfileProps> = ({
  isRealMode,
  realTxEvidence,
  realCase,
  simulatedProfile = MOCK_CUSTOMER_PROFILE,
}) => {
  const [activeTab, setActiveTab] = useState<'datos' | 'productos' | 'transacciones'>('datos');

  return (
    <div className="panel-card" style={{ height: '240px' }}>
      <div className="panel-header">
        <span>Perfil del Cliente</span>
      </div>

      <div className="tabs-header" role="tablist">
        <button
          className={`tab-btn ${activeTab === 'datos' ? 'active' : ''}`}
          onClick={() => setActiveTab('datos')}
          type="button"
          role="tab"
          aria-selected={activeTab === 'datos'}
        >
          Datos
        </button>
        <button
          className={`tab-btn ${activeTab === 'productos' ? 'active' : ''}`}
          onClick={() => setActiveTab('productos')}
          type="button"
          role="tab"
          aria-selected={activeTab === 'productos'}
        >
          Productos
        </button>
        <button
          className={`tab-btn ${activeTab === 'transacciones' ? 'active' : ''}`}
          onClick={() => setActiveTab('transacciones')}
          type="button"
          role="tab"
          aria-selected={activeTab === 'transacciones'}
        >
          Transacciones
        </button>
      </div>

      <div className="tab-content">
        {activeTab === 'datos' && (
          <div>
            {isRealMode ? (
              <div className="empty-state">
                <p style={{ fontWeight: 600, color: 'var(--text-ink)', marginBottom: '0.3rem' }}>
                  Evidencia Real del Caso
                </p>
                <p style={{ fontSize: '0.8rem', color: 'var(--text-muted)' }}>
                  ID Caso: <strong>{realCase?.caseId || 'demo-case-1'}</strong>
                </p>
                <p style={{ fontSize: '0.8rem', color: 'var(--text-muted)' }}>
                  Estado Caso: <strong>{realCase?.status || 'N/A'}</strong>
                </p>
                <div style={{ marginTop: '0.8rem', fontStyle: 'italic', fontSize: '0.78rem', color: 'var(--text-muted)' }}>
                  ℹ️ Sin datos personales adicionales: el back todavía no expone esta información (Brecha de integración).
                </div>
              </div>
            ) : (
              <div style={{ display: 'flex', flexDirection: 'column', gap: '0.4rem', fontSize: '0.85rem' }}>
                <div><strong>Nombre:</strong> {simulatedProfile.name}</div>
                <div><strong>Identificación:</strong> {simulatedProfile.documentId}</div>
                <div><strong>Email:</strong> {simulatedProfile.email}</div>
                <div><strong>Teléfono:</strong> {simulatedProfile.phone}</div>
              </div>
            )}
          </div>
        )}

        {activeTab === 'productos' && (
          <div>
            {isRealMode ? (
              <div className="empty-state">
                Sin datos: el back todavía no expone esta información.
              </div>
            ) : (
              <div style={{ display: 'flex', flexDirection: 'column', gap: '0.5rem' }}>
                {simulatedProfile.products?.map((prod) => (
                  <div
                    key={prod.id}
                    style={{
                      padding: '0.4rem 0.6rem',
                      border: '1px solid var(--line-color)',
                      borderRadius: 'var(--control-radius)',
                      fontSize: '0.8rem',
                      display: 'flex',
                      justifyContent: 'space-between',
                    }}
                  >
                    <div>
                      <div style={{ fontWeight: 600 }}>{prod.name}</div>
                      <div style={{ color: 'var(--text-muted)', fontSize: '0.72rem' }}>{prod.type}</div>
                    </div>
                    <span style={{ color: 'var(--green-primary)', fontWeight: 600, fontSize: '0.75rem' }}>
                      {prod.status}
                    </span>
                  </div>
                ))}
              </div>
            )}
          </div>
        )}

        {activeTab === 'transacciones' && (
          <div>
            {isRealMode ? (
              <div>
                {realTxEvidence ? (
                  <div
                    style={{
                      padding: '0.5rem',
                      border: '1px solid var(--blue-primary)',
                      borderRadius: 'var(--control-radius)',
                      backgroundColor: 'var(--blue-soft)',
                      fontSize: '0.8rem',
                    }}
                  >
                    <div style={{ fontWeight: 700, color: 'var(--blue-primary)' }}>
                      Tx: {realTxEvidence.transactionId}
                    </div>
                    <div>Monto (Bucket): <strong>{realTxEvidence.amountBucket}</strong> ({realTxEvidence.currency})</div>
                    <div>Estado Tx: <strong>{realTxEvidence.status}</strong></div>
                    <div style={{ fontSize: '0.7rem', color: 'var(--text-muted)', marginTop: '0.2rem' }}>
                      Origen: {realTxEvidence.provenance} ({realTxEvidence.version})
                    </div>
                  </div>
                ) : (
                  <div className="empty-state">
                    Cargando evidencia de transacción...
                  </div>
                )}
              </div>
            ) : (
              <div style={{ display: 'flex', flexDirection: 'column', gap: '0.5rem' }}>
                {simulatedProfile.transactions?.map((tx) => (
                  <div
                    key={tx.id}
                    style={{
                      padding: '0.4rem 0.6rem',
                      border: '1px solid var(--line-color)',
                      borderRadius: 'var(--control-radius)',
                      fontSize: '0.78rem',
                    }}
                  >
                    <div style={{ display: 'flex', justifyContent: 'space-between', fontWeight: 600 }}>
                      <span>{tx.merchant}</span>
                      <span>{tx.amountBucket}</span>
                    </div>
                    <div style={{ color: 'var(--text-muted)', fontSize: '0.7rem' }}>
                      {tx.date} — Estado: {tx.status}
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        )}
      </div>
    </div>
  );
};
