import {
  DemoActor,
  DemoFixtures,
  SafeSession,
  ConversationSnapshot,
  TransactionEvidence,
  DisputeEvidence,
  DisputeCase,
  Problem,
  VerifiedAction,
} from './types';

const API_BASE = '/backend';

async function handleResponse<T>(res: Response): Promise<{ ok: boolean; data?: T; problem?: Problem; status: number }> {
  const status = res.status;
  const contentType = res.headers.get('content-type') || '';
  
  if (contentType.includes('application/problem+json') || !res.ok) {
    try {
      const problem: Problem = await res.json();
      return { ok: false, problem, status };
    } catch {
      return {
        ok: false,
        status,
        problem: {
          type: 'about:blank',
          title: res.statusText || 'Error de petición',
          status,
          code: `HTTP-${status}`,
          category: 'INTERNAL',
          detail_key: 'http_error',
          behavior: {
            retryable: 'never',
            financial_effect: 'none',
            human_action: 'contact_support',
            agent_hint: 'ABORT_AND_REPORT',
            retry_after_s: null,
          },
          correlation: { trace_id: 'local' },
          occurred_at: new Date().toISOString(),
        },
      };
    }
  }

  try {
    const data = await res.json();
    return { ok: true, data, status };
  } catch {
    return { ok: true, status };
  }
}

export async function getLiveHealth() {
  const res = await fetch(`${API_BASE}/v1/health/live`, { credentials: 'include' });
  return handleResponse<{ status: string; service: string }>(res);
}

