'use client';

import React, { useState, useRef, useEffect } from 'react';
import { ConversationMessage, SafeAttachment } from '../lib/types';
import { uploadAttachment } from '../lib/backend';

interface ChatProps {
  messages: ConversationMessage[];
  onSendMessage: (text: string, attachmentIds?: string[]) => void;
  isTyping?: boolean;
  systemAlert?: string | null;
  problemAlert?: string | null;
  placeholder?: string;
  isRealMode?: boolean;
}

export const Chat: React.FC<ChatProps> = ({
  messages,
  onSendMessage,
  isTyping = false,
  systemAlert = null,
  problemAlert = null,
  placeholder = 'Escribe tu mensaje aquí... (Enter para enviar, Shift+Enter para nueva línea)',
  isRealMode = false,
}) => {
  const [inputText, setInputText] = useState('');
  const [uploading, setUploading] = useState(false);
  const [attachments, setAttachments] = useState<SafeAttachment[]>([]);
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages, isTyping, systemAlert, problemAlert]);

  const handleKeyDown = (e: React.KeyboardEvent<HTMLTextAreaElement>) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSend();
    }
  };

  const handleSend = () => {
    const trimmed = inputText.trim();
    if (!trimmed && attachments.length === 0) return;

    const attachmentIds = attachments.map((a) => a.attachmentId);
    onSendMessage(trimmed, attachmentIds);
    setInputText('');
    setAttachments([]);
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    if (attachments.length >= 3) {
      alert('Máximo 3 adjuntos por mensaje.');
      return;
    }

    setUploading(true);

    if (isRealMode) {
      const kind = file.type.startsWith('audio') ? 'audio' : 'image';
      const res = await uploadAttachment(file, kind);
      if (res.ok && res.data) {
        setAttachments((prev) => [
          ...prev,
          {
            attachmentId: res.data.attachmentId || `att-${Date.now()}`,
            kind,
            mediaType: file.type || 'image/png',
            status: 'ready',
          },
        ]);
      } else {
        alert(`Error al subir adjunto: ${res.problem?.title || 'Fallo desconocido'}`);
      }
    } else {
      // Simulated upload
      setTimeout(() => {
        const kind = file.type.startsWith('audio') ? 'audio' : 'image';
        setAttachments((prev) => [
          ...prev,
          {
            attachmentId: `sim-att-${Date.now()}`,
            kind,
            mediaType: file.type || 'image/png',
            status: 'ready',
          },
        ]);
      }, 500);
    }
    setUploading(false);
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const removeAttachment = (id: string) => {
    setAttachments((prev) => prev.filter((a) => a.attachmentId !== id));
  };

  const suggestions = [
    'Quiero revisar una compra no reconocida de 450 USD',
    '¿Cuál es el estado de mi solicitud de disputa?',
    'Necesito ayuda con el bloqueo preventivo de mi tarjeta',
  ];

  return (
    <div className="chat-container">
      <div className="chat-messages" role="log" aria-label="Mensajes de conversación">
        {messages.length === 0 && (
          <div style={{ padding: '2rem 1rem', textAlign: 'center' }}>
            <h3 style={{ fontSize: '1.1rem', color: 'var(--text-ink)', marginBottom: '0.5rem' }}>
              👋 Asistente Virtual de Soporte para Disputas
            </h3>
            <p style={{ fontSize: '0.88rem', color: 'var(--text-muted)', marginBottom: '1.5rem' }}>
              Escribe tu consulta o selecciona una sugerencia para iniciar la atención:
            </p>
            <div style={{ display: 'flex', flexDirection: 'column', gap: '0.5rem', maxWidth: '400px', margin: '0 auto' }}>
              {suggestions.map((suggestion, idx) => (
                <button
                  key={idx}
                  onClick={() => onSendMessage(suggestion)}
                  type="button"
                  style={{
                    backgroundColor: 'var(--blue-soft)',
                    color: 'var(--blue-primary)',
                    border: '1px solid #BFD2FB',
                    borderRadius: '8px',
                    padding: '0.6rem 0.9rem',
                    fontSize: '0.85rem',
                    textAlign: 'left',
                    cursor: 'pointer',
                    transition: 'all 0.2s ease',
                  }}
                >
                  💡 {suggestion}
                </button>
              ))}
            </div>
          </div>
        )}

        {messages.map((msg, idx) => {
          const isUser = msg.role === 'customer';
          const isBackoffice = msg.role === 'backoffice';
          const isAssistant = msg.role === 'assistant';

          let bubbleClass = 'assistant';
          if (isUser) bubbleClass = 'customer';
          if (isBackoffice) bubbleClass = 'backoffice';

          return (
            <div key={msg.messageId ? `${msg.messageId}-${idx}` : `msg-${idx}`} className={`chat-bubble ${bubbleClass}`}>
              <div style={{ fontSize: '0.72rem', opacity: 0.8, marginBottom: '0.2rem', fontWeight: 600 }}>
                {isUser ? 'Cliente' : isBackoffice ? 'Operador (Backoffice)' : 'Asistente AI'}
              </div>

              <div>{msg.content}</div>

              {msg.attachments && msg.attachments.length > 0 && (
                <div style={{ marginTop: '0.5rem', display: 'flex', gap: '0.4rem', flexWrap: 'wrap' }}>
                  {msg.attachments.map((att, attIdx) => (
                    <div
                      key={att.attachmentId ? `${att.attachmentId}-${attIdx}` : `att-${attIdx}`}
                      style={{
                        backgroundColor: 'rgba(255,255,255,0.2)',
                        padding: '0.2rem 0.5rem',
                        borderRadius: '4px',
                        fontSize: '0.75rem',
                      }}
                    >
                      📎 {att.kind === 'image' ? 'Imagen' : 'Audio'}: {att.attachmentId.slice(0, 8)}
                    </div>
                  ))}
                </div>
              )}

              <div style={{ fontSize: '0.68rem', opacity: 0.65, marginTop: '0.3rem', textAlign: 'right' }}>
                {msg.createdAt ? new Date(msg.createdAt).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }) : ''}
              </div>
            </div>
          );
        })}

        {systemAlert && (
          <div className="chat-bubble system">
            ⚠️ <strong>Aviso del Sistema:</strong> {systemAlert}
          </div>
        )}

        {problemAlert && (
          <div className="chat-bubble system-problem">
            🛑 <strong>Error del Backend:</strong> {problemAlert}
          </div>
        )}

        {isTyping && (
          <div className="typing-indicator">
            <span>El asistente está escribiendo...</span>
          </div>
        )}

        <div ref={messagesEndRef} />
      </div>

      <div className="chat-input-area">
        {attachments.length > 0 && (
          <div className="attachment-preview">
            {attachments.map((att) => (
              <div key={att.attachmentId} className="attachment-chip">
                <span>📎 {att.kind === 'image' ? 'Imagen' : 'Audio'}</span>
                <button
                  onClick={() => removeAttachment(att.attachmentId)}
                  type="button"
                  style={{ border: 'none', background: 'none', cursor: 'pointer', color: 'var(--red-primary)' }}
                >
                  ✕
                </button>
              </div>
            ))}
          </div>
        )}

        <div className="chat-form">
          <input
            type="file"
            ref={fileInputRef}
            onChange={handleFileUpload}
            style={{ display: 'none' }}
            accept="image/*,audio/*"
          />
          <button
            className="btn-secondary"
            onClick={() => fileInputRef.current?.click()}
            disabled={uploading || attachments.length >= 3}
            type="button"
            title="Adjuntar imagen o audio (máx 3)"
            style={{ padding: '0.65rem', minWidth: '42px' }}
          >
            {uploading ? '...' : '📎'}
          </button>

          <textarea
            className="chat-input"
            value={inputText}
            onChange={(e) => setInputText(e.target.value)}
            onKeyDown={handleKeyDown}
            placeholder={placeholder}
            rows={1}
          />

          <button
            className="btn-primary"
            onClick={handleSend}
            disabled={!inputText.trim() && attachments.length === 0}
            type="button"
            style={{ padding: '0.65rem 1.2rem', height: '42px' }}
          >
            Enviar
          </button>
        </div>
      </div>
    </div>
  );
};
